window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-d71cc403cc664ad5"]={"versions": [{"id": "FIG-d71cc403cc664ad5", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Darstellung der Schlafsequenz II (Sleep Sequence II mit Polling / kontinuierlicher Überwachung im Halte-/Schlafmodus) im AUTOSAR Classic Platform Schichtenmodell. Das Diagramm spezifiziert die Interaktion des ECU State Managers (<code>EcuM</code>, System Services) mit dem Microcontroller Driver (<code>Mcu</code>, Microcontroller Abstraction Layer / MCAL), anwendungsspezifischem bzw. plattformspezifischem Integrationscode (<code>Integration Code</code>) sowie generischen Weckquellen-Treibern (<code>Wakeup Source</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Lebenslinien und Schnittstellen:</p>\n<ul class=\"fig-list\">\n<li><code>«module» EcuM</code>: ECU State Manager zur Ablaufsteuerung der Schlaf- und Weckbehandlung.</li>\n<li><code>Integration Code</code>: Anwenderspezifische Callouts und Integrationsroutinen.</li>\n<li><code>«module» Mcu</code>: MCU-Treiber zur Umschaltung des System- bzw. Prozessormodus.</li>\n<li><code>«module» Wakeup Source</code>: Generische Repräsentation der Treiber für Weckquellen (z. B. Can, Lin, Gpt).</li>\n</ul>\n<p class=\"fig-p\">Aufgerufene Schnittstellen und Funktionssignaturen:</p>\n<ul class=\"fig-list\">\n<li><code>Mcu_SetMode(Mcu_ModeType)</code>: Synchroner Aufruf an den MCU-Treiber zur Aktivierung des Schlafpfads/Modus.</li>\n<li><code>EcuM_SleepActivity()</code>: Callout an den Integrationscode zur Ausführung von Hintergrund- oder zyklischen Tätigkeiten während des Schlafs.</li>\n<li><code>EcuM_CheckWakeup(EcuM_WakeupSourceType)</code>: Callout an den Integrationscode zur Prüfung und Weiterleitung an Weckquellen.</li>\n<li><code>&lt;Module&gt;_CheckWakeup()</code>: Treiberspezifischer Aufruf zur Abfrage des Weckstatus an der Hardware.</li>\n<li><code>EcuM_SetWakeupEvent(EcuM_WakeupSourceType)</code>: Callback zur Signalisierung eines erkannten Weckereignisses an den EcuM.</li>\n<li><code>EcuM_GetPendingWakeupEvents(EcuM_WakeupSourceType)</code>: Interne Funktion / Selbstaufruf zur Überprüfung noch anstehender Weckereignisse.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Ablauf der Schlafsequenz II:</p>\n<ol class=\"fig-list\">\n<li><code>EcuM</code> leitet den Schlafzustand über den synchronen Aufruf <code>Mcu_SetMode(Mcu_ModeType)</code> an das <code>Mcu</code>-Modul ein.</li>\n<li>Eintritt in die übergeordnete Schleife <code>loop WHILE no pending wakeup events</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>EcuM</code> ruft die Integrationsfunktion <code>EcuM_SleepActivity()</code> auf.</li>\n<li>Innerhalb der Schlafaktivität folgt eine geschachtelte Schleife <code>loop FOR all wakeup sources that need polling</code>:</li>\n<li><code>EcuM</code> ruft <code>EcuM_CheckWakeup(EcuM_WakeupSourceType)</code> im <code>Integration Code</code> auf.</li>\n<li>Der Integrationscode delegiert dies via <code>&lt;Module&gt;_CheckWakeup()</code> an das jeweilige Modul der <code>Wakeup Source</code>.</li>\n<li>Bedingter Block <code>opt Wakeup detected</code>: Erkennt das Modul ein Weckereignis, meldet es dieses asynchron bzw. über den Callback <code>EcuM_SetWakeupEvent(EcuM_WakeupSourceType)</code> an <code>EcuM</code> zurück.</li>\n<li><code>&lt;Module&gt;_CheckWakeup()</code> und <code>EcuM_CheckWakeup()</code> kehren zum Aufrufer zurück.</li>\n<li>Nach Abarbeitung der Polling-Schleife prüft <code>EcuM</code> über den internen Selbstaufruf <code>EcuM_GetPendingWakeupEvents(EcuM_WakeupSourceType)</code> den Zustand anstehender Weckereignisse.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Die Schleife <code>WHILE no pending wakeup events</code> terminiert, sobald ein Weckereignis vorliegt.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert das normative Interaktionsmuster für Low-Power-Modi ohne automatischen CPU-Halt bzw. mit aktivem Polling von Weckquellen:</p>\n<ul class=\"fig-list\">\n<li>Der Integrationscode ist dafür verantwortlich, <code>EcuM_CheckWakeup</code> auf die konkreten hardwarebezogenen <code>&lt;Module&gt;_CheckWakeup</code>-APIs der konfigurierten Treiber abzubilden.</li>\n<li>Weckquellen, die nicht interruptgetrieben arbeiten, müssen im Polling-Zyklus erfasst werden.</li>\n<li>Die Schleifenbedingung garantiert, dass der Sleep-Zustand erst verlassen wird, wenn mindestens ein Weckereignis über <code>EcuM_SetWakeupEvent</code> registriert und durch <code>EcuM_GetPendingWakeupEvents</code> verifiziert wurde.</li>\n</ul>"}, {"id": "FIG-ff485b011da2014f", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Darstellung der Schlafsequenz II (Sleep Sequence II mit Polling / kontinuierlicher Überwachung im Halte-/Schlafmodus) im AUTOSAR Classic Platform Schichtenmodell. Das Diagramm spezifiziert die Interaktion des ECU State Managers (<code>EcuM</code>, System Services) mit dem Microcontroller Driver (<code>Mcu</code>, Microcontroller Abstraction Layer / MCAL), anwendungsspezifischem bzw. plattformspezifischem Integrationscode (<code>Integration Code</code>) sowie generischen Weckquellen-Treibern (<code>Wakeup Source</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Lebenslinien und Schnittstellen:</p>\n<ul class=\"fig-list\">\n<li><code>«module» EcuM</code>: ECU State Manager zur Ablaufsteuerung der Schlaf- und Weckbehandlung.</li>\n<li><code>Integration Code</code>: Anwenderspezifische Callouts und Integrationsroutinen.</li>\n<li><code>«module» Mcu</code>: MCU-Treiber zur Umschaltung des System- bzw. Prozessormodus.</li>\n<li><code>«module» Wakeup Source</code>: Generische Repräsentation der Treiber für Weckquellen (z. B. Can, Lin, Gpt).</li>\n</ul>\n<p class=\"fig-p\">Aufgerufene Schnittstellen und Funktionssignaturen:</p>\n<ul class=\"fig-list\">\n<li><code>Mcu_SetMode(Mcu_ModeType)</code>: Synchroner Aufruf an den MCU-Treiber zur Aktivierung des Schlafpfads/Modus.</li>\n<li><code>EcuM_SleepActivity()</code>: Callout an den Integrationscode zur Ausführung von Hintergrund- oder zyklischen Tätigkeiten während des Schlafs.</li>\n<li><code>EcuM_CheckWakeup(EcuM_WakeupSourceType)</code>: Callout an den Integrationscode zur Prüfung und Weiterleitung an Weckquellen.</li>\n<li><code>&lt;Module&gt;_CheckWakeup()</code>: Treiberspezifischer Aufruf zur Abfrage des Weckstatus an der Hardware.</li>\n<li><code>EcuM_SetWakeupEvent(EcuM_WakeupSourceType)</code>: Callback zur Signalisierung eines erkannten Weckereignisses an den EcuM.</li>\n<li><code>EcuM_GetPendingWakeupEvents(EcuM_WakeupSourceType)</code>: Interne Funktion / Selbstaufruf zur Überprüfung noch anstehender Weckereignisse.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Ablauf der Schlafsequenz II:</p>\n<ol class=\"fig-list\">\n<li><code>EcuM</code> leitet den Schlafzustand über den synchronen Aufruf <code>Mcu_SetMode(Mcu_ModeType)</code> an das <code>Mcu</code>-Modul ein.</li>\n<li>Eintritt in die übergeordnete Schleife <code>loop WHILE no pending wakeup events</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>EcuM</code> ruft die Integrationsfunktion <code>EcuM_SleepActivity()</code> auf.</li>\n<li>Innerhalb der Schlafaktivität folgt eine geschachtelte Schleife <code>loop FOR all wakeup sources that need polling</code>:</li>\n<li><code>EcuM</code> ruft <code>EcuM_CheckWakeup(EcuM_WakeupSourceType)</code> im <code>Integration Code</code> auf.</li>\n<li>Der Integrationscode delegiert dies via <code>&lt;Module&gt;_CheckWakeup()</code> an das jeweilige Modul der <code>Wakeup Source</code>.</li>\n<li>Bedingter Block <code>opt Wakeup detected</code>: Erkennt das Modul ein Weckereignis, meldet es dieses asynchron bzw. über den Callback <code>EcuM_SetWakeupEvent(EcuM_WakeupSourceType)</code> an <code>EcuM</code> zurück.</li>\n<li><code>&lt;Module&gt;_CheckWakeup()</code> und <code>EcuM_CheckWakeup()</code> kehren zum Aufrufer zurück.</li>\n<li>Nach Abarbeitung der Polling-Schleife prüft <code>EcuM</code> über den internen Selbstaufruf <code>EcuM_GetPendingWakeupEvents(EcuM_WakeupSourceType)</code> den Zustand anstehender Weckereignisse.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Die Schleife <code>WHILE no pending wakeup events</code> terminiert, sobald ein Weckereignis vorliegt.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert das normative Interaktionsmuster für Low-Power-Modi ohne automatischen CPU-Halt bzw. mit aktivem Polling von Weckquellen:</p>\n<ul class=\"fig-list\">\n<li>Der Integrationscode ist dafür verantwortlich, <code>EcuM_CheckWakeup</code> auf die konkreten hardwarebezogenen <code>&lt;Module&gt;_CheckWakeup</code>-APIs der konfigurierten Treiber abzubilden.</li>\n<li>Weckquellen, die nicht interruptgetrieben arbeiten, müssen im Polling-Zyklus erfasst werden.</li>\n<li>Die Schleifenbedingung garantiert, dass der Sleep-Zustand erst verlassen wird, wenn mindestens ein Weckereignis über <code>EcuM_SetWakeupEvent</code> registriert und durch <code>EcuM_GetPendingWakeupEvents</code> verifiziert wurde.</li>\n</ul>"}, {"id": "FIG-01303e2e6cb9a2c8", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Darstellung der Schlafsequenz II (Sleep Sequence II mit Polling / kontinuierlicher Überwachung im Halte-/Schlafmodus) im AUTOSAR Classic Platform Schichtenmodell. Das Diagramm spezifiziert die Interaktion des ECU State Managers (<code>EcuM</code>, System Services) mit dem Microcontroller Driver (<code>Mcu</code>, Microcontroller Abstraction Layer / MCAL), anwendungsspezifischem bzw. plattformspezifischem Integrationscode (<code>Integration Code</code>) sowie generischen Weckquellen-Treibern (<code>Wakeup Source</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Lebenslinien und Schnittstellen:</p>\n<ul class=\"fig-list\">\n<li><code>«module» EcuM</code>: ECU State Manager zur Ablaufsteuerung der Schlaf- und Weckbehandlung.</li>\n<li><code>Integration Code</code>: Anwenderspezifische Callouts und Integrationsroutinen.</li>\n<li><code>«module» Mcu</code>: MCU-Treiber zur Umschaltung des System- bzw. Prozessormodus.</li>\n<li><code>«module» Wakeup Source</code>: Generische Repräsentation der Treiber für Weckquellen (z. B. Can, Lin, Gpt).</li>\n</ul>\n<p class=\"fig-p\">Aufgerufene Schnittstellen und Funktionssignaturen:</p>\n<ul class=\"fig-list\">\n<li><code>Mcu_SetMode(Mcu_ModeType)</code>: Synchroner Aufruf an den MCU-Treiber zur Aktivierung des Schlafpfads/Modus.</li>\n<li><code>EcuM_SleepActivity()</code>: Callout an den Integrationscode zur Ausführung von Hintergrund- oder zyklischen Tätigkeiten während des Schlafs.</li>\n<li><code>EcuM_CheckWakeup(EcuM_WakeupSourceType)</code>: Callout an den Integrationscode zur Prüfung und Weiterleitung an Weckquellen.</li>\n<li><code>&lt;Module&gt;_CheckWakeup()</code>: Treiberspezifischer Aufruf zur Abfrage des Weckstatus an der Hardware.</li>\n<li><code>EcuM_SetWakeupEvent(EcuM_WakeupSourceType)</code>: Callback zur Signalisierung eines erkannten Weckereignisses an den EcuM.</li>\n<li><code>EcuM_GetPendingWakeupEvents(EcuM_WakeupSourceType)</code>: Interne Funktion / Selbstaufruf zur Überprüfung noch anstehender Weckereignisse.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Ablauf der Schlafsequenz II:</p>\n<ol class=\"fig-list\">\n<li><code>EcuM</code> leitet den Schlafzustand über den synchronen Aufruf <code>Mcu_SetMode(Mcu_ModeType)</code> an das <code>Mcu</code>-Modul ein.</li>\n<li>Eintritt in die übergeordnete Schleife <code>loop WHILE no pending wakeup events</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>EcuM</code> ruft die Integrationsfunktion <code>EcuM_SleepActivity()</code> auf.</li>\n<li>Innerhalb der Schlafaktivität folgt eine geschachtelte Schleife <code>loop FOR all wakeup sources that need polling</code>:</li>\n<li><code>EcuM</code> ruft <code>EcuM_CheckWakeup(EcuM_WakeupSourceType)</code> im <code>Integration Code</code> auf.</li>\n<li>Der Integrationscode delegiert dies via <code>&lt;Module&gt;_CheckWakeup()</code> an das jeweilige Modul der <code>Wakeup Source</code>.</li>\n<li>Bedingter Block <code>opt Wakeup detected</code>: Erkennt das Modul ein Weckereignis, meldet es dieses asynchron bzw. über den Callback <code>EcuM_SetWakeupEvent(EcuM_WakeupSourceType)</code> an <code>EcuM</code> zurück.</li>\n<li><code>&lt;Module&gt;_CheckWakeup()</code> und <code>EcuM_CheckWakeup()</code> kehren zum Aufrufer zurück.</li>\n<li>Nach Abarbeitung der Polling-Schleife prüft <code>EcuM</code> über den internen Selbstaufruf <code>EcuM_GetPendingWakeupEvents(EcuM_WakeupSourceType)</code> den Zustand anstehender Weckereignisse.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Die Schleife <code>WHILE no pending wakeup events</code> terminiert, sobald ein Weckereignis vorliegt.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert das normative Interaktionsmuster für Low-Power-Modi ohne automatischen CPU-Halt bzw. mit aktivem Polling von Weckquellen:</p>\n<ul class=\"fig-list\">\n<li>Der Integrationscode ist dafür verantwortlich, <code>EcuM_CheckWakeup</code> auf die konkreten hardwarebezogenen <code>&lt;Module&gt;_CheckWakeup</code>-APIs der konfigurierten Treiber abzubilden.</li>\n<li>Weckquellen, die nicht interruptgetrieben arbeiten, müssen im Polling-Zyklus erfasst werden.</li>\n<li>Die Schleifenbedingung garantiert, dass der Sleep-Zustand erst verlassen wird, wenn mindestens ein Weckereignis über <code>EcuM_SetWakeupEvent</code> registriert und durch <code>EcuM_GetPendingWakeupEvents</code> verifiziert wurde.</li>\n</ul>"}, {"id": "FIG-dc6ecb77c316bddb", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Darstellung der Schlafsequenz II (Sleep Sequence II mit Polling / kontinuierlicher Überwachung im Halte-/Schlafmodus) im AUTOSAR Classic Platform Schichtenmodell. Das Diagramm spezifiziert die Interaktion des ECU State Managers (<code>EcuM</code>, System Services) mit dem Microcontroller Driver (<code>Mcu</code>, Microcontroller Abstraction Layer / MCAL), anwendungsspezifischem bzw. plattformspezifischem Integrationscode (<code>Integration Code</code>) sowie generischen Weckquellen-Treibern (<code>Wakeup Source</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Lebenslinien und Schnittstellen:</p>\n<ul class=\"fig-list\">\n<li><code>«module» EcuM</code>: ECU State Manager zur Ablaufsteuerung der Schlaf- und Weckbehandlung.</li>\n<li><code>Integration Code</code>: Anwenderspezifische Callouts und Integrationsroutinen.</li>\n<li><code>«module» Mcu</code>: MCU-Treiber zur Umschaltung des System- bzw. Prozessormodus.</li>\n<li><code>«module» Wakeup Source</code>: Generische Repräsentation der Treiber für Weckquellen (z. B. Can, Lin, Gpt).</li>\n</ul>\n<p class=\"fig-p\">Aufgerufene Schnittstellen und Funktionssignaturen:</p>\n<ul class=\"fig-list\">\n<li><code>Mcu_SetMode(Mcu_ModeType)</code>: Synchroner Aufruf an den MCU-Treiber zur Aktivierung des Schlafpfads/Modus.</li>\n<li><code>EcuM_SleepActivity()</code>: Callout an den Integrationscode zur Ausführung von Hintergrund- oder zyklischen Tätigkeiten während des Schlafs.</li>\n<li><code>EcuM_CheckWakeup(EcuM_WakeupSourceType)</code>: Callout an den Integrationscode zur Prüfung und Weiterleitung an Weckquellen.</li>\n<li><code>&lt;Module&gt;_CheckWakeup()</code>: Treiberspezifischer Aufruf zur Abfrage des Weckstatus an der Hardware.</li>\n<li><code>EcuM_SetWakeupEvent(EcuM_WakeupSourceType)</code>: Callback zur Signalisierung eines erkannten Weckereignisses an den EcuM.</li>\n<li><code>EcuM_GetPendingWakeupEvents(EcuM_WakeupSourceType)</code>: Interne Funktion / Selbstaufruf zur Überprüfung noch anstehender Weckereignisse.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Ablauf der Schlafsequenz II:</p>\n<ol class=\"fig-list\">\n<li><code>EcuM</code> leitet den Schlafzustand über den synchronen Aufruf <code>Mcu_SetMode(Mcu_ModeType)</code> an das <code>Mcu</code>-Modul ein.</li>\n<li>Eintritt in die übergeordnete Schleife <code>loop WHILE no pending wakeup events</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>EcuM</code> ruft die Integrationsfunktion <code>EcuM_SleepActivity()</code> auf.</li>\n<li>Innerhalb der Schlafaktivität folgt eine geschachtelte Schleife <code>loop FOR all wakeup sources that need polling</code>:</li>\n<li><code>EcuM</code> ruft <code>EcuM_CheckWakeup(EcuM_WakeupSourceType)</code> im <code>Integration Code</code> auf.</li>\n<li>Der Integrationscode delegiert dies via <code>&lt;Module&gt;_CheckWakeup()</code> an das jeweilige Modul der <code>Wakeup Source</code>.</li>\n<li>Bedingter Block <code>opt Wakeup detected</code>: Erkennt das Modul ein Weckereignis, meldet es dieses asynchron bzw. über den Callback <code>EcuM_SetWakeupEvent(EcuM_WakeupSourceType)</code> an <code>EcuM</code> zurück.</li>\n<li><code>&lt;Module&gt;_CheckWakeup()</code> und <code>EcuM_CheckWakeup()</code> kehren zum Aufrufer zurück.</li>\n<li>Nach Abarbeitung der Polling-Schleife prüft <code>EcuM</code> über den internen Selbstaufruf <code>EcuM_GetPendingWakeupEvents(EcuM_WakeupSourceType)</code> den Zustand anstehender Weckereignisse.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Die Schleife <code>WHILE no pending wakeup events</code> terminiert, sobald ein Weckereignis vorliegt.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert das normative Interaktionsmuster für Low-Power-Modi ohne automatischen CPU-Halt bzw. mit aktivem Polling von Weckquellen:</p>\n<ul class=\"fig-list\">\n<li>Der Integrationscode ist dafür verantwortlich, <code>EcuM_CheckWakeup</code> auf die konkreten hardwarebezogenen <code>&lt;Module&gt;_CheckWakeup</code>-APIs der konfigurierten Treiber abzubilden.</li>\n<li>Weckquellen, die nicht interruptgetrieben arbeiten, müssen im Polling-Zyklus erfasst werden.</li>\n<li>Die Schleifenbedingung garantiert, dass der Sleep-Zustand erst verlassen wird, wenn mindestens ein Weckereignis über <code>EcuM_SetWakeupEvent</code> registriert und durch <code>EcuM_GetPendingWakeupEvents</code> verifiziert wurde.</li>\n</ul>"}], "trans": [{"from": "FIG-d71cc403cc664ad5", "to": "FIG-ff485b011da2014f", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-ff485b011da2014f", "to": "FIG-01303e2e6cb9a2c8", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-01303e2e6cb9a2c8", "to": "FIG-dc6ecb77c316bddb", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
